//! The attributes of the Frames FindFrame and PickAxes produce, checked
//! against the C library.
//!
//! `overlay_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/overlay_probe.c`. The result of a SubFrame is
//! overlaid first by the target and then by the template, each through its
//! own class's Overlay (frame.c:11033), which transfers the attributes that
//! class defines and only onto a result of its own class.

#[path = "overlay_oracle/cases.rs"]
mod cases;

use ast_core::frames::{
    BasicFrameBuilder, CmpFrame, DynFrame, FluxFrame, FluxSystem, Frame, FrameRef, SkyFrame,
    SkySystem, SpecFrame, SpecSystem, TimeFrame, TimeSystem, pick_axes,
};

/// J1990 and J2010 as TDB Modified Julian Dates.
const J1990: f64 = 47892.0;
const J2010: f64 = 55197.0;

/// A plain Frame with the given axis count and settings.
fn frame(naxes: usize, f: impl FnOnce(&mut dyn Frame)) -> DynFrame {
    let mut fr: DynFrame = Box::new(BasicFrameBuilder::new(naxes).build().unwrap());
    f(fr.as_mut());
    fr
}

fn found(target: &dyn Frame, template: &dyn Frame) -> Option<DynFrame> {
    let fs = target
        .snapshot()
        .find_frame_template(template, "")
        .unwrap()?;
    Some(fs.frame(FrameRef::Current).unwrap().snapshot())
}

fn sky(system: SkySystem) -> SkyFrame {
    let mut f = SkyFrame::unset_system();
    f.set_system(system);
    f
}

fn run(name: &str) -> Option<DynFrame> {
    match name {
        "frame_pick" => {
            let f = frame(2, |f| {
                f.set_title("Picked").unwrap();
                f.set_domain("PIX").unwrap();
                f.set_digits(3).unwrap();
                f.set_epoch_mjd(J1990).unwrap();
                f.set_label(1, "X").unwrap();
                f.set_label(2, "Y").unwrap();
                f.set_unit(1, "m").unwrap();
            });
            Some(pick_axes(f.as_ref(), &[2, 1]).unwrap().0)
        }
        "sky_target_frame_template" => {
            let t = frame(2, |f| {
                f.set_domain("SKY").unwrap();
                f.set_title("Hello").unwrap();
                f.set_digits(9).unwrap();
            });
            found(&sky(SkySystem::Fk5), t.as_ref())
        }
        "sky_pick_one" => {
            let mut s = sky(SkySystem::Fk5);
            s.set_epoch_mjd(J1990);
            Frame::set_title(&mut s, "Sky").unwrap();
            Frame::set_digits(&mut s, 5).unwrap();
            Some(pick_axes(&s, &[1]).unwrap().0)
        }
        "flux_target_frame_template" => {
            let mut f = FluxFrame::new(FluxSystem::FluxDen);
            f.set_spec_val(1.4e9);
            let t = frame(1, |f| {
                f.set_domain("FLUX").unwrap();
                f.set_title("TT").unwrap();
                f.set_label(1, "LL").unwrap();
                f.set_epoch_mjd(J2010).unwrap();
                f.set_digits(9).unwrap();
            });
            found(&f, t.as_ref())
        }
        "spec_target_frame_template" => {
            let mut s = SpecFrame::new(SpecSystem::Freq);
            s.set_unit(1, "GHz").unwrap();
            let t = frame(1, |f| {
                f.set_domain("SPECTRUM").unwrap();
                f.set_title("Spec").unwrap();
                f.set_label(1, "Nu").unwrap();
                f.set_digits(8).unwrap();
            });
            found(&s, t.as_ref())
        }
        "time_target_frame_template" => {
            let t = frame(1, |f| {
                f.set_domain("TIME").unwrap();
                f.set_title("When").unwrap();
                f.set_label(1, "T").unwrap();
                f.set_digits(11).unwrap();
            });
            found(&TimeFrame::new(TimeSystem::Mjd), t.as_ref())
        }
        "time_system_change" => {
            let mut f = TimeFrame::new(TimeSystem::Mjd);
            f.set_label(1, "Mine").unwrap();
            Frame::set_title(&mut f, "Mine").unwrap();
            found(&f, &TimeFrame::new(TimeSystem::Jd))
        }
        "spec_system_change" => {
            let mut f = SpecFrame::new(SpecSystem::Freq);
            f.set_label(1, "Mine").unwrap();
            Frame::set_title(&mut f, "Mine").unwrap();
            found(&f, &SpecFrame::new(SpecSystem::Wavelen))
        }
        "cmp_template_plain_target" => {
            let target = frame(2, |f| f.set_domain("SPECTRUM-").unwrap());
            let mut spec = SpecFrame::new(SpecSystem::Wavelen);
            spec.clear_system().unwrap();
            Frame::set_title(&mut spec, "CmpSpec").unwrap();
            spec.set_label(1, "Freq").unwrap();
            let t = CmpFrame::new(Box::new(spec), frame(1, |_| {}));
            found(target.as_ref(), &t)
        }
        "spec_pick_padded" => {
            let mut s = SpecFrame::new(SpecSystem::Freq);
            s.set_unit(1, "GHz").unwrap();
            Some(pick_axes(&s, &[1, 0]).unwrap().0)
        }
        "spec_wave_pick_padded" => Some(
            pick_axes(&SpecFrame::new(SpecSystem::Wavelen), &[1, 0])
                .unwrap()
                .0,
        ),
        "time_pick_padded" => Some(
            pick_axes(&TimeFrame::new(TimeSystem::Jd), &[1, 0])
                .unwrap()
                .0,
        ),
        "flux_pick_padded" => {
            let mut f = FluxFrame::with_spec_val(1.4e9, None);
            f.set_system(FluxSystem::FluxDen).unwrap();
            Some(pick_axes(&f, &[1, 0]).unwrap().0)
        }
        other => panic!("no Rust set-up for case {other}"),
    }
}

#[test]
fn overlay_results_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, want) in cases::CASES {
        let got = run(name).map(|f| {
            (
                f.title().unwrap(),
                f.domain().to_string(),
                f.digits(),
                f.test_epoch(),
                f.epoch_mjd(),
                f.label(1).unwrap(),
                f.unit(1).unwrap(),
            )
        });
        let want = want.map(|(t, d, dg, te, e, l, u)| {
            (
                t.to_string(),
                d.to_string(),
                dg,
                te,
                e,
                l.to_string(),
                u.to_string(),
            )
        });
        if got != want {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// PickAxes rejects an axis selected twice (`AST__SELIN`), gives a UnitMap
/// for an identity selection, and gives an axis beyond the Frame's a bad
/// output (frame.c `PickAxes`, `ValidateAxisSelection`, `SubFrame`). Each
/// outcome was checked against the C library.
#[test]
fn pick_axes_selection_rules_match_the_c_library() {
    use ast_core::constants::BAD_VALUE;
    use ast_core::error::ErrorCode;
    use ast_core::mappings::{PermMap, UnitMap};

    let f = BasicFrameBuilder::new(2).build().unwrap();
    let err = pick_axes(&f, &[1, 1]).expect_err("duplicate axes rejected");
    assert_eq!(err.code(), ErrorCode::Selin);

    let (_, map) = pick_axes(&f, &[1, 2]).unwrap();
    assert!(map.as_any().is::<UnitMap>());
    let (_, map) = pick_axes(&f, &[2, 1]).unwrap();
    assert!(map.as_any().is::<PermMap>());

    let (picked, map) = pick_axes(&f, &[1, 3]).unwrap();
    assert_eq!(picked.naxes(), 2);
    let (x, y) = map.tran2(&[5.0], &[6.0], true).unwrap();
    assert_eq!((x[0], y[0]), (5.0, BAD_VALUE));
}
